import math
def quant_snr_db(N):
    # ideal SNR of an N-bit converter, full-scale sine
    return 6.02*N + 1.76

def lsb(v_fs, N):
    return v_fs / (2**N)

print(round(quant_snr_db(16),1), 'dB')   # 98.1 dB
print(lsb(10.0, 16))                      # ~153 uV per count

# place a profile sample on a flux surface
def to_psi_n(R, Z, equilibrium):
    psi   = equilibrium.psi(R, Z)          # interpolated flux
    psi_n = (psi - equilibrium.psi_axis) / (
             equilibrium.psi_lcfs - equilibrium.psi_axis)
    return max(0.0, min(1.0, psi_n))

def strain_delta(strain_now, preload_baseline):
    # microstrain change attributable to operation
    return strain_now - preload_baseline

def within_envelope(delta, lo, hi):
    return lo <= delta <= hi   # per-gauge limits from structural model

import math
def capacity_bps(bandwidth_hz, snr_linear):
    # Shannon-Hartley capacity of a diagnostic channel
    return bandwidth_hz * math.log2(1 + snr_linear)

# a 500 kHz magnetics channel at 40 dB SNR
capacity_bps(500e3, 10**(40/10))   # ~6.6 Mbit/s

import math
def mutual_information(p_xy, p_x, p_y):
    mi = 0.0
    for (x,y),pxy in p_xy.items():
        if pxy>0:
            mi += pxy*math.log2(pxy/(p_x[x]*p_y[y]))
    return mi   # bits that Y reveals about X
